template <class T>
class UTree
{                   
public:
// Дополнительные типы данных
typedef string NameT;
typedef int UIdT;
typedef vector<UIdT> ULongIdT;
typedef vector<UIdT> ULongIdIterator;

protected: // Статические данные
// Разделительный символ в длинных именах узлов дерева
char Separator;

protected: // Данные
// Id узла
UIdT Id;

// имя узла
NameT Name;

// данные узла
T Data;

// Указатель на корень узла
UTree<T> *Root;

// Список ветвей узла
vector<UTree<T>* > SubTree;

// Указатель на текущий подузел
mutable UTree<T> *Current;

// Опциональная индексация для быстрого поиска по имени (O(1) вместо O(n))
// Индекс автоматически используется при количестве узлов >= INDEX_THRESHOLD
mutable std::unordered_map<NameT, UTree<T>*> NameIndex;
mutable bool IndexValid;
static const size_t INDEX_THRESHOLD = 10; // Порог для включения индексации

public: // Методы
// --------------------------
// Конструкторы и деструкторы
// --------------------------
UTree(void)
{
 Root=0;
 Current=this;
 Name="Root";
 Separator='.';
 IndexValid=false;
};

UTree(const UTree<T> &node)
{
 UTree<T> *newnode;

 Root=0;
 Current=this;
 Name=node.Name;
 Data=node.Data;
 IndexValid=false;

 SubTree.resize(node.SubTree.size());

 for(size_t i=0;i<SubTree.size();i++)
  {
   newnode=0;
   newnode=new UTree<T>;
   if(!newnode)
    throw NoFreeMemException(this);

   *newnode=*node.SubTree[i];
   newnode->Root=this;
   SubTree[i]=newnode;
  }

 if(node.Current)
  Current=&(operator [](node.Current->GetFullId(node)));
};

virtual ~UTree(void)
{
 Clear();
};
