#ifndef UQUEUE_H
#define UQUEUE_H

#include <vector>
#include <list>
#include <string>

namespace RDK {

using namespace std;

template<typename Ty>
class UQueue
{
private:
// Начальный максимальный размер очереди
enum { INIT_SIZE = 1024 };

protected: // Данные
// Данные очереди
vector<Ty> m_pData;

// Число данных в очерди
unsigned int Size;

// Максимально доступный размер очереди
unsigned int MaxSize;

// Индекс первого элемента
unsigned int Front;

// Индекс последнего элемента
unsigned int Back;

public: // Методы
// --------------------------
// Конструкторы и деструкторы
// --------------------------
// Создает пустую очередь
UQueue(void)
{
 Front=0;
 Back=0;
 Size = 0;
 MaxSize = 0;
};

// Создает очередь с резервированым максимальным размером
explicit UQueue(size_t size)
{
 MaxSize = size;
 Size = 0;
 m_pData.resize(size);
 Front=0;
 Back=Size-1;
};

// Создает очередь заполненную данными из вектора vec
explicit UQueue(const std::vector<Ty>& vec)
{
 Size = MaxSize = vec.size();
 m_pData=vec;
 Front = 0;
 Back = Size-1;
};

~UQueue(void)
{
};
// --------------------------

// --------------------------
// Методы доступа к данным
// --------------------------
// Возвращает первый элемент
Ty&    front(void)
{
 return    m_pData[Front];
};

// Возвращает последний элемент
Ty&    back(void)
{
 return    m_pData[Back];
};

// Оператор доступа к элементам по индексу
// Индекс считается от начала очереди
Ty& operator [] (int i)
{
 if(Front+i<MaxSize)
  return m_pData[Front+i];
 else
  return m_pData[Front+i-MaxSize];
}

// Возвращает true если очередь пуста
bool empty(void)
{
 return (size() == 0);
};

// Возвращает число элементов данных в очереди
size_t size(void)
{
 return    Size;
};
// --------------------------

