bool operator == (const T *p) const
{ return (PData == p)?true:false; };

bool operator != (const T *p) const
{ return (PData != p)?true:false; };

operator bool (void) const
{ return (PData)?true:false; };

T* operator -> (void)
{
 return PData;
};

T& operator * (void)
{
 if(!PData)
  throw UFEUsingZeroPtr();

 return *PData;
};

operator T* (void) const
{
 return PData;
}
// --------------------------
};

