	MMatrix<T,4,4> res;
	MVector<T,6> anglesANDshifts;
	for(int i=0;i<3;i++)
		anglesANDshifts(i)=shifts(i);
	for(int i=3;i<6;i++)
		anglesANDshifts(i)=angles(i-3);
	res=CalcObjectPositionMatrix(anglesANDshifts, seqmat);
	return res;
}

