	My(1,0)=0;			My(1,1)=1; My(1,2)=0;
	My(2,0)=-sin_beta;  My(2,1)=0; My(2,2)=cos_beta;

	Mz(0,0)=cos_alpha; Mz(0,1)=-sin_alpha;	Mz(0,2)=0;
