  memset(MDMatrix<T>::Data,0,this->GetRows()*sizeof(T));
 else
 {
  T* p=MDMatrix<T>::Data;
  for(int i=0;i<MDMatrix<T>::GetRows();i++)
   *p++=defvalue;
 }
}

