 if(FindFilesList(path, "*", true, results) != 0)
  return 1;

 for(size_t i=0;i<results.size();i++)
  if(RemoveFile((std::string(path)+"\\"+results[i]).c_str()) != 0)
   return 2;

 BOOL res=::RemoveDirectory(path);
 if(!res)
  return 3;

