// --------------------------
// Методы декодирования
// --------------------------
/// Инициализирует процесс обработки новой команды
void URpcCommand::PrepareProcess(void)
{
 if(IsPrepared)
  return;
 FunctionName.clear();
 ComponentName.clear();
 ChannelIndex=-1;
 CmdId=0;
 IsProcessed=false;
 IsDecoded=false;
 APrepareProcess();
 IsPrepared=true;
}

/// Осуществляет декодирование основных данных и заполняет соответствующие поля
bool URpcCommand::DecodeBasicData(void)
{
 if(IsDecoded)
  return true;

 PrepareProcess();

 if(!ADecodeBasicData())
  return false;

 IsDecoded=true;
 return true;
}
