  code=UG_EDGE_CODE_BOTTOM;
 if(point.X > rect.X2())
  code=code + UG_EDGE_CODE_RIGHT;
 else
 if(point.X < rect.X1())
  code = code + UG_EDGE_CODE_LEFT;
 return code;
}

