void UGraphWidget::GraphSeriesBuffer::Append(double xValue, double yValue, int capacity)
{
    if (capacity <= 0)
        capacity = kDefaultGraphBuffer;

    if (X.size() >= capacity) {
        const int removeCount = X.size() - capacity + 1;
        X.remove(0, removeCount);
        Y.remove(0, removeCount);
    }

    X.append(xValue);
    Y.append(yValue);
}

