std::string UOllamaNativeProvider::ollamaHost() const
{
    std::string host = m_profile.base_url;
    while(!host.empty() && host.back() == '/')
        host.pop_back();
    const std::string suffix_v1 = "/v1";
    if(host.size() >= suffix_v1.size()
       && host.compare(host.size() - suffix_v1.size(), suffix_v1.size(), suffix_v1) == 0)
        host.erase(host.size() - suffix_v1.size());
    return host;
}

LLMCompletionResult UOllamaNativeProvider::parseResponse(const std::string& body,
                                                         std::string& error) const
{
    LLMCompletionResult result;
    try
    {
        const nlohmann::json j = nlohmann::json::parse(body);
        if(j.contains("error"))
        {
            result.ok = false;
            result.error_message = j["error"].dump();
            return result;
        }
        if(j.contains("message"))
        {
            const auto& message = j["message"];
            if(message.contains("content") && !message["content"].is_null())
                result.text = message["content"].get<std::string>();
            if(message.contains("tool_calls"))
            {
                for(const auto& tc : message["tool_calls"])
                {
                    LLMToolCall call;
                    call.id = tc.value("id", "");
                    if(tc.contains("function"))
                    {
                        call.name = tc["function"].value("name", "");
                        const std::string args_str = tc["function"].value("arguments", "{}");
                        call.arguments = nlohmann::json::parse(args_str);
                    }
                    result.tool_calls.push_back(call);
                }
            }
        }
        result.ok = true;
    }
    catch(const std::exception& ex)
    {
        error = ex.what();
        result.ok = false;
        result.error_message = error;
    }
    return result;
}

LLMCompletionResult UOllamaNativeProvider::chat(const std::vector<LLMMessage>& messages,
                                                const LLMCompletionOptions& opts)
{
    LLMCompletionResult result;
    const std::string lang = opts.response_language.empty() ? "en" : opts.response_language;
    const std::vector<LLMMessage> prepared =
        prepareMessagesForOllama(m_profile, messages, lang);

    nlohmann::json body;
    body["model"] = m_profile.model;
    body["stream"] = false;
    body["messages"] = buildOpenAiChatMessagesJson(prepared);
    if(opts.max_tokens > 0)
        body["options"] = {{"num_predict", opts.max_tokens}};
    if(!opts.tools_for_api.empty())
    {
        body["tools"] = opts.tools_for_api;
        if(opts.tool_choice)
            body["tool_choice"] = *opts.tool_choice;
        else
            body["tool_choice"] = "auto";
    }

    const std::string url = ollamaHost() + "/api/chat";
    auto resp = m_http.postJson(url, body.dump(), m_profile.api_key);
    if(!resp.error.empty())
    {
        result.ok = false;
        result.error_message = resp.error;
        return result;
    }
    if(resp.status_code < 200 || resp.status_code >= 300)
    {
        result.ok = false;
        result.error_message = "HTTP " + std::to_string(resp.status_code) + ": " + resp.body;
        return result;
    }
    std::string parse_err;
    return parseResponse(resp.body, parse_err);
}

