 if(!EnableShowFlag)
 {
  *Output=Canvas;
  return true;
 }

 if(!Input->GetData())
 {
  *Output=Canvas;
  return true;
 }

 Graphics.SetCanvas(&Canvas);

 Graphics.SetPenWidth(PenWidth);
 Graphics.SetPenColor(PenColor);

 if(!AFSCalculate())
  return false;

