T getMax(T** Input,const int N,int &nRow,int &nCol)
{
    T rMax=Input[0][1];
    nRow = 0;
    nCol = 1;

    for(int i=0;i<N;++i)
        for(int j=0;j<N;++j)
            if(i!=j)
                if( abs(Input[i][j]) > rMax )
                {
                    rMax = abs(Input[i][j]);
                    nRow = i ;
                    nCol = j ;
                }
    return rMax;
}


