UArduinoBoardProfile UArduinoBoardProfileUtil::profileForKind(UArduinoBoardKind kind)
{
    UArduinoBoardProfile p;
    p.kind = kind;
    if (kind == UArduinoBoardKind::Mega2560) {
        p.mcu = "atmega2560";
        p.programmer = "wiring";
        p.protocol = "wiring";
    } else {
        p.mcu = "atmega328p";
        p.programmer = "arduino";
        p.protocol = "arduino";
