    const std::string encoded = RDK::UArduinoPropertyString::toStdProperty(value);
    return QByteArray(encoded.c_str(), static_cast<int>(encoded.size()));
}

void applyUnicodeFriendlyFont(QWidget* widget)
{
    if (!widget)
        return;
    QFont font = QApplication::font();
    font.setStyleStrategy(QFont::PreferDefault);
    widget->setFont(font);
}

QPlainTextEdit* createStatusLogWidget(QWidget* parent)
{
    auto* edit = new QPlainTextEdit(parent);
    applyUnicodeFriendlyFont(edit);
    edit->setReadOnly(true);
    edit->setLineWrapMode(QPlainTextEdit::WidgetWidth);
    edit->setTextInteractionFlags(Qt::TextSelectableByMouse | Qt::TextSelectableByKeyboard);
    edit->setTabChangesFocus(true);
    edit->setMinimumHeight(72);
    edit->setMaximumHeight(180);
    edit->setPlaceholderText(QObject::tr("Status and log messages (Ctrl+C to copy selection)"));
    return edit;
}

void setStatusLogText(QPlainTextEdit* widget, const QString& text)
{
    if (!widget)
        return;
    if (widget->toPlainText() == text)
        return;
    widget->setPlainText(text);
}

