// 2 - аналогично 1, но формула y=exp(-Kx)*Gain
// 3 - аналогично 1, ExpCoeff вычисляется автоматически
// 4 - адаптация по формуле y=Gain*(1.0+input);
RDK::UProperty<int,NReceptor, ptPubParameter> OutputAdaptationMode;

