  return false;

 DefaultComponentClassId=ForbiddenId;
 NetType=0;
 NumLayers=1;
 LayerWidth=1;
 LayerHeight=1;
 ReceptorFieldWidth=1;
 ReceptorFieldHeight=1;
 LinksOrganizationMode=0;
 LinkDistance=1;

 return true;
