UGEngineControlWidget* resolveEngineControlWidget(QWidget* source)
{
    QObject* current = source;
    while(current)
    {
        if(auto* main = qobject_cast<UGEngineControlWidget*>(current))
            return main;
        current = current->parent();
    }
    return nullptr;
}
}

