static std::string makeConfirmationId()
{
    static std::mt19937 rng{std::random_device{}()};
    static std::uniform_int_distribution<int> dist(0, 15);
    const char* hex = "0123456789abcdef";
    std::string id;
    for(int i = 0; i < 32; ++i)
        id += hex[dist(rng)];
    return id;
}

