namespace {

float scoreKeywords(const std::string& lower, const std::vector<const char*>& words, float weight)
{
    float score = 0.f;
    for(const char* w : words)
    {
        if(lower.find(w) != std::string::npos)
            score += weight;
    }
    return score;
}

} // namespace

IntentParseResult ULLMIntentParser::parseDetailed(const std::string& user_text) const
{
    std::string lower = user_text;
    for(char& c : lower)
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));

    const float plan_s = scoreKeywords(lower, {"план", "спланируй", "шаги", "plan ", "steps", "roadmap", "сначала"}, 1.2f);
    const float mutate_s =
        scoreKeywords(lower,
                      {"добав", "создай", "удали", "измени", "сохран", "загруз", "открой", "закрой", "конфиг",
                       "конфигурац", "проект", "configuration", "project", "project.ini", "скопируй",
                       "переимен", "запусти расч", "останови расч",
                       "add ", "create ", "create config", "new config", "new configuration", "remove ", "delete ",
                       "save ", "load ", "set ", "connect ", "open config", "close config", "copy config",
                       "rename config", "создай конфиг", "новый конфиг", "новая конфигурация"},
                      1.0f);

    // Russian graph-mutation verbs: "соедини", "соединить", "связать", etc.
    // The intent parser relies on keyword substring scoring; add broad stems to avoid missing tool-calls.
    const float connect_kw_s = scoreKeywords(lower, {"соедин", "связ"}, 1.0f);
    const float mutate_s_with_connect = std::max(mutate_s, connect_kw_s);
    const float explain_s =
        scoreKeywords(lower, {"почему", "объясни", "explain", "why ", "как работает", "how does"}, 1.0f);
    const float query_s =
        scoreKeywords(lower,
                      {"arduino", "firmware", "hardware", "датчик", "плата", "что", "какие", "покажи",
                       "список", "опиши", "найди", "валидируй", "проверь конфиг", "validate configuration", "what",
                       "list", "show", "describe", "search", "find ", "tool", "tools", "имена инструментов"},
                      1.2f);

    IntentParseResult result;
    result.method = "rules";
    float best = query_s;
    result.kind = LLMIntentKind::Query;

    if(plan_s > best)
    {
        best = plan_s;
        result.kind = LLMIntentKind::Plan;
    }
    if(mutate_s_with_connect > best)
    {
        best = mutate_s_with_connect;
        result.kind = LLMIntentKind::Mutate;
    }
    if(explain_s > best)
    {
        best = explain_s;
        result.kind = LLMIntentKind::Explain;
    }
    if(query_s > best)
    {
        best = query_s;
        result.kind = LLMIntentKind::Query;
    }

    const float total = plan_s + mutate_s + explain_s + query_s + 0.01f;
    result.confidence = std::min(1.f, best / total);
    return result;
}

LLMIntentKind ULLMIntentParser::parse(const std::string& user_text) const
{
    return parseDetailed(user_text).kind;
}

IntentParseResult ULLMIntentParser::parseWithOptionalLlm(ILLMProvider* provider,
                                                        const std::string& user_text) const
{
    IntentParseResult rules = parseDetailed(user_text);
    if(!provider)
        return rules;

    const char* env = std::getenv("NMSDK_LLM_INTENT_LLM");
    if(!env || env[0] != '1')
        return rules;

    std::vector<LLMMessage> msgs;
    LLMMessage system;
    system.role = LLMMessage::Role::System;
    system.content =
        "Classify user intent. Reply with exactly one word: query, mutate, explain, or plan.";
    msgs.push_back(system);
    LLMMessage user;
    user.role = LLMMessage::Role::User;
    user.content = user_text;
    msgs.push_back(user);

    LLMCompletionOptions opts;
    opts.max_tokens = 8;
    opts.temperature = 0.f;
    opts.tools_for_api.clear();

    const LLMCompletionResult completion = provider->chat(msgs, opts);
    if(!completion.ok)
        return rules;

#include "ULLMAgentManifestBuilder.h"

#include "ULLMLibraryScopeHint.h"

#include <sstream>

namespace RDK::LLM {

std::string buildAgentManifest(const ULLMToolRegistry& registry, const ToolFilter& filter,
                               const std::size_t max_chars, const std::string& user_text)
{
    std::ostringstream oss;
    const std::vector<LLMToolDefinition> tools = registry.listForLlmApi(filter);

    oss << libraryScopeHintManifestSection(detectLibraryScopeFromUserText(user_text));

    oss << "## Tools (" << tools.size() << " available)\n";
    for(const LLMToolDefinition& tool : tools)
    {
        oss << "- " << tool.name << " [" << (tool.kind == LLMToolKind::Write ? "write" : "read");
        if(tool.requires_confirmation)
            oss << ", hitl";
        oss << "]: " << tool.description << "\n";
    }

    oss << "## Knowledge\n";
    oss << "- search_project_docs(scope=docs|sources|all) for product docs and implementation.\n";
    oss << "## Rules\n";
    oss << "- Use write tools only for explicit mutate requests.\n";
    oss << "- Graph mutations: add_component, set_property, connect_components (and disconnect_components) as requested.\n";
    oss << "- Prefer one tool call per step, then inspect tool result.\n";
    oss << "- If no tool can satisfy a mutate request, respond NO_SUITABLE_TOOL.\n";

    std::string manifest = oss.str();
    if(manifest.size() > max_chars)
        manifest.resize(max_chars);
    return manifest;
}

